    fig, axes = plt.subplots(
        nrows, ncols,
        figsize=(5 * ncols, 4 * nrows),
        squeeze=False,
    )

    for idx, (cond_key, cond_data) in enumerate(sorted(valid_conds.items())):
        row, col = divmod(idx, ncols)
